<template>
  <div class="work-page"><div class="page-heading"><div><h1>我的工作</h1><p>待办、我发起的事项和需要关注的业务记录。</p></div><el-button :loading="loading" @click="load"><el-icon><Refresh /></el-icon>刷新</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" /><el-row :gutter="16"><el-col v-for="item in summary" :key="item.key" :xs="12" :sm="6"><el-card shadow="never" class="summary-card"><span>{{ item.label }}</span><strong>{{ item.count }}</strong></el-card></el-col></el-row><el-card shadow="never"><div class="toolbar"><el-input v-model="search" clearable placeholder="搜索事项" class="search" @keyup.enter="load"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="section" placeholder="事项分类" @change="load"><el-option value="all" label="全部事项" /><el-option v-for="item in sections" :key="item.key" :value="item.key" :label="item.label" /></el-select><el-select v-model="sortBy" @change="load"><el-option value="id:desc" label="最新事项" /><el-option value="deadline:asc" label="截止日期升序" /><el-option value="priority:desc" label="优先级降序" /></el-select><el-button :disabled="!selected.length" :loading="batching" @click="completeBatch">批量完成 ({{ selected.length }})</el-button></div><el-table :data="filteredItems" row-key="id" empty-text="当前没有待处理事项" @selection-change="selected=$event"><el-table-column type="selection" width="48" /><el-table-column label="事项" min-width="280"><template #default="{row}"><strong>{{ row.title || row.label || '未命名事项' }}</strong><small class="subline">{{ row.section_label || row.section || '业务事项' }}</small></template></el-table-column><el-table-column label="优先级" width="110"><template #default="{row}"><el-tag :type="priorityType(row.priority)" size="small">{{ priorityLabel(row.priority) }}</el-tag></template></el-table-column><el-table-column prop="deadline" label="截止时间" width="150" /><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button v-for="action in row.actions || []" :key="action.key" link type="primary" size="small" @click="runAction(row,action)">{{ action.label }}</el-button><el-button link size="small" @click="openItem(row)">打开</el-button></template></el-table-column></el-table></el-card></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { Refresh, Search } from '@element-plus/icons-vue';import { completeMyWorkItem, completeMyWorkItems, executeButton, fetchMyWorkSummary } from '@/api/odoo';import type { MyWorkItem } from '@/types/contracts'
const router=useRouter();const loading=ref(false);const error=ref('');const search=ref('');const section=ref('all');const sortBy=ref('id:desc');const summary=ref<Array<{key:string;label:string;count:number}>>([]);const items=ref<MyWorkItem[]>([]);const sections=ref<Array<{key:string;label:string}>>([]);const selected=ref<MyWorkItem[]>([]);const batching=ref(false);const filteredItems=computed(()=>{const list=section.value==='all'?items.value:items.value.filter((i)=>i.section===section.value);return search.value?list.filter((i)=>`${i.title||i.label} ${i.section_label||i.section}`.toLowerCase().includes(search.value.toLowerCase())):list});function priorityType(v?:string){return v==='high'||v==='urgent'?'danger':v==='medium'?'warning':'info'}function priorityLabel(v?:string){return v==='high'||v==='urgent'?'高优先级':v==='medium'?'中优先级':'普通'}async function load(){loading.value=true;error.value='';try{const [field,dir]=sortBy.value.split(':');const result=await fetchMyWorkSummary({section:section.value,search:search.value,sortBy:field,sortDir:dir});summary.value=result.summary||[];const source=result.product_workspace?.sections||result.sections||[];sections.value=source.map((s)=>({key:s.key,label:s.label}));items.value=result.product_workspace?.sections?.flatMap((s)=>s.items||[])||result.items||result.sections?.flatMap((s)=>s.items||[])||[]}catch(cause){error.value=cause instanceof Error?cause.message:'工作事项加载失败'}finally{loading.value=false}}async function completeBatch(){batching.value=true;try{await completeMyWorkItems(selected.value.map((i)=>Number(i.id)).filter(Boolean));ElMessage.success('批量完成成功');selected.value=[];await load()}catch(cause){ElMessage.error(cause instanceof Error?cause.message:'批量完成失败')}finally{batching.value=false}}async function runAction(item:MyWorkItem,action:NonNullable<MyWorkItem['actions']>[number]){try{if(action.intent==='my.work.complete'&&item.id)await completeMyWorkItem(item.id);else await executeButton({model:item.model||'',recordId:Number(item.record_id||item.id),button:{name:action.key,type:'object'}});ElMessage.success(`${action.label}已完成`);await load()}catch(cause){ElMessage.error(cause instanceof Error?cause.message:`${action.label}失败`)}}function openItem(item:MyWorkItem){if(item.model&&item.record_id)void router.push({name:'Record',params:{model:item.model,id:item.record_id},query:{mode:'view'}});else ElMessage.info('当前事项没有可用业务入口')}onMounted(load)
</script><style scoped>.work-page{display:grid;gap:16px}.page-heading{display:flex;justify-content:space-between;align-items:flex-start}.page-heading h1{margin:0 0 8px;font-size:26px}.page-heading p{margin:0;color:#909399}.summary-card{border:0}.summary-card span{display:block;color:#909399;font-size:13px}.summary-card strong{display:block;font-size:27px;margin-top:12px}.toolbar{display:flex;gap:10px;align-items:center;margin-bottom:18px}.search{max-width:360px}.subline{display:block;color:#909399;margin-top:6px;font-size:12px}@media(max-width:800px){.toolbar{flex-wrap:wrap}.search{max-width:none;width:100%}.toolbar .el-select,.toolbar .el-button{flex:1;min-width:130px}}</style>
